"""Render every experiment output into one readable Markdown file."""
import sys, json, glob, os
sys.stdout.reconfigure(encoding="utf-8")
out = ["# Content quality experiments, 18 October 2026: raw outputs\n",
       "Generated by the scripts in this folder. Runs are named `<condition>-<week>-<model>`.",
       "B0 = current production angle prompt and contract; B1 = B0 plus the WIA knowledge base; P1 = proposed strategist prompt, knowledge base and lean card.",
       "BR0 = current brief writer and BriefDocument contract (with the full voice guide and strategy in the brand bundle); BR1 = proposed editorial brief.\n"]
def ledger():
    rows = [json.loads(l) for l in open("ledger.jsonl", encoding="utf-8") if l.strip()]
    rows = [r for r in rows if not r.get("error")]
    out.append("## Cost ledger\n\n| Run | Model | Input tokens | Output tokens | USD |\n|---|---|---:|---:|---:|")
    for r in rows: out.append(f"| {r['run_id']} | {r['model']} | {r['prompt_tokens']} | {r['completion_tokens']} | {r['cost']:.4f} |")
    out.append(f"| **Total** | | | | **{sum(r['cost'] for r in rows):.3f}** |\n")
def angles(rid):
    d = json.load(open(f"runs/{rid}.json", encoding="utf-8")); o = d["output"]
    out.append(f"## {rid}\n")
    if "week_summary" in o:
        out.append(f"**Week summary:** {o['week_summary']}\n")
        for a in sorted(o["angles"], key=lambda x: x["rank"]):
            out.append(f"### {a['rank']}. {a['title']}\n- **Purpose/type:** {a['pillar']} / {a['content_type']}\n- **Audience:** {a['audience']}\n- **Core perspective:** {a['core_perspective']}\n- **Why it matters:** {a['why_it_matters']}\n- **WIA in action:** {a['wia_in_action']}\n- **Offer connection:** {a['offer_connection']}\n- **Moments:** {', '.join(a['moment_ids'])}\n- **Evidence points:** " + " | ".join(a["evidence_points"]) + "\n- **Verify before publishing:** " + (" | ".join(a["verify_before_publishing"]) or "none") + f"\n- **Why selected:** {a['why_selected']}\n")
        out.append("**Internal insights**\n"); out.extend([f"- {i['insight']} *Use:* {i['use']}" for i in o["internal_insights"]])
        out.append("\n**Considered and not selected**\n"); out.extend([f"- {i['idea']}: {i['reason']}" for i in o["considered_not_selected"]])
    else:
        for a in o["angles"]:
            out.append(f"### {a['title']}\n- **Purpose/type:** {a['strategic_purpose']} / {a['content_type']}\n- **Audience:** {a['audience']}\n- **Opportunity:** {a['content_opportunity']}\n- **Core perspective:** {a['core_perspective']}\n- **Tension:** {a['tension']}\n- **WIA expertise:** {a['wia_expertise_in_action']}\n- **Service relevance:** {a['service_relevance']}\n- **Selection reason:** {a['selection_reason']}\n- **Qualifiers:** " + " | ".join(a["qualifiers"]) + "\n- **Risks:** " + " | ".join(a["risks"]) + f"\n- **Self-scores:** " + ", ".join(f"{k} {v}" for k, v in a["quality"].items() if k != "reasons") + "\n")
        out.append("**Internal insights**\n"); out.extend([f"- {i['insight']}" for i in o["internal_insights"]])
        out.append("\n**Coverage notes**\n"); out.extend([f"- {c}" for c in o["coverage_notes"]])
    out.append("")
def brief(rid):
    o = json.load(open(f"runs/{rid}.json", encoding="utf-8"))["output"]
    out.append(f"## {rid}\n\n```json\n{json.dumps(o, ensure_ascii=False, indent=1)}\n```\n")
def judges():
    out.append("## Judge outputs\n")
    for f in sorted(glob.glob("runs/J*.json")):
        o = json.load(open(f, encoding="utf-8"))["output"]
        out.append(f"### {os.path.basename(f)[:-5]}\n\n```json\n{json.dumps(o, ensure_ascii=False, indent=1)}\n```\n")
ledger()
for rid in ["B0-week2-gpt-6-luna", "B0-week2-gpt-6.1-sol", "B1-week2-gpt-6.1-sol", "P1-week2-gpt-6-luna", "P1-week2-gpt-6.1-sol", "P1-week2-claude-sonnet-5",
            "B0-week1-gpt-6.1-sol", "P1-week1-gpt-6.1-sol", "P1-week1-claude-sonnet-5"]:
    if os.path.exists(f"runs/{rid}.json"): angles(rid)
for rid in ["BR0-tour-gpt-6.1-sol", "BR1-tour-gpt-6.1-sol"]: brief(rid)
judges()
open(sys.argv[1], "w", encoding="utf-8").write("\n".join(out))
print("written", sys.argv[1])
